9.6 Vacunación sin barreras.', (select id from grupos_res3100 where numeral = '11.2'), (select id from servicios_res3100 where numeral = '11.2.3'), '11.2', '11.2.3', 'Estándar de Procesos Prioritarios', 'baja', 'intramural'),
